create table organizations (id text primary key, name text not null, target_margin decimal not null default 0.40, loaded_labor_rate decimal not null default 0);
create table customers (id text primary key, organization_id text not null references organizations(id), external_id text, name text not null);
create table agreements (id text primary key, organization_id text not null references organizations(id), customer_id text not null references customers(id), external_id text, annual_price decimal not null, starts_on date, renews_on date, status text not null default 'active');
create table service_visits (id text primary key, organization_id text not null references organizations(id), customer_id text not null references customers(id), agreement_id text references agreements(id), completed_at timestamp, labor_hours decimal not null default 0, labor_cost decimal not null default 0, material_cost decimal not null default 0, other_cost decimal not null default 0);
create table margin_snapshots (id text primary key, agreement_id text not null references agreements(id), actual_cost decimal not null, gross_margin decimal not null, recommended_price decimal not null, annual_upside decimal not null, calculated_at timestamp not null);
create table imports (id text primary key, organization_id text not null references organizations(id), kind text not null, filename text not null, row_count integer not null default 0, status text not null default 'pending');
